// Wrap the tsc-emitted ESM client half in the DeepSeek Harness web plugin
// loader format.
//
// DSH serves every web client plugin through /plugins/??… as a classic script
// and expects each file to call `window.__ModuleLoader__.load({ id, factory })`
// (see @deepseek-ai/dsh-client-* for the reference shape). A bare `export`
// statement is a SyntaxError there and aborts the whole web boot, so the
// compiled lib/client.js cannot ship as ESM.
//
// The transform is deliberately narrow: src/client.ts only exports top-level
// declarations, and any other export form fails the build instead of silently
// producing a broken bundle.
import { readFileSync, writeFileSync, rmSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const clientPath = join(root, 'lib', 'client.js')
const mapPath = `${clientPath}.map`
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))

const source = readFileSync(clientPath, 'utf8')
if (source.includes('__ModuleLoader__.load')) {
  console.log('[build-client] already wrapped — skipping')
  process.exit(0)
}

const unsupported = source.match(/^export\s+(default\b|\{|\*)/m)
if (unsupported) {
  console.error(`[build-client] unsupported export form: ${unsupported[0].trim()}`)
  process.exit(1)
}

const exported = []
const body = source
  .replace(/^export\s+(async\s+function|function|class|const|let|var)\s+([A-Za-z_$][\w$]*)/gm, (_m, kind, name) => {
    exported.push(name)
    return `${kind} ${name}`
  })
  .replace(/^\/\/# sourceMappingURL=.*$/m, '')
  .trimEnd()

const leftover = body.match(/^export\b.*$/m)
if (leftover) {
  console.error(`[build-client] unhandled export: ${leftover[0].trim()}`)
  process.exit(1)
}

if (exported.length === 0) {
  console.error('[build-client] no top-level exports found — refusing to emit an inert plugin')
  process.exit(1)
}

const wrapped = `// dsh-scale client half — wrapped for the DeepSeek Harness web plugin loader.
// Generated by scripts/build-client.mjs from the tsc output; do not edit.
window.__ModuleLoader__.load({
\tid: ${JSON.stringify(pkg.name)},
\tfactory: (require) => {
\t\tvar module = { exports: {} };
\t\tvar exports = module.exports;
\t\tObject.defineProperty(exports, Symbol.toStringTag, { value: "Module" });
${body}
${exported.map(name => `\t\texports.${name} = ${name};`).join('\n')}
\t\treturn module.exports;
\t}
});
`

writeFileSync(clientPath, wrapped)
// Positions no longer match the map after wrapping; ship no map rather than a wrong one.
if (existsSync(mapPath)) rmSync(mapPath)
console.log(`[build-client] wrapped ${pkg.name} (exports: ${exported.join(', ')})`)
